import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.PrintWriter;import java.util.StringTokenizer;import java.io.IOException;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));PrintWriter out = new PrintWriter(System.out);StringTokenizer st = new StringTokenizer(br.readLine());int t = Integer.parseInt(st.nextToken());while (t-- > 0) {st = new StringTokenizer(br.readLine());int x = Integer.parseInt(st.nextToken());boolean possible = false;for (int i = 0; i <= 11; i++) {int rem = x - i * 111;if (rem >= 0 && rem % 11 == 0) {possible = true;break;}}if (possible) {out.println("YES");} else {out.println("NO");}}out.flush();out.close();}}